/** All three-cut orders, independent raw collisions, trusted entry refusal and all-checks barrier. */
public final class ContextUniversalContinuationRefutationRunner {
    static List<List<Snapshot>> permutations(List<Snapshot> values){List<List<Snapshot>> all=new ArrayList<>();permute(new ArrayList<>(),values,all);return all;}
    static void permute(List<Snapshot> prefix,List<Snapshot> rest,List<List<Snapshot>> all){if(rest.isEmpty()){all.add(prefix);return;}for(int i=0;i<rest.size();++i){List<Snapshot> p=new ArrayList<>(prefix),r=new ArrayList<>(rest);p.add(r.remove(i));permute(p,r,all);}}
    static void reject(Frame f,SessionRun s,int round){ContextUniversalGroupedRoundsRunner.refuted(s.result,round);require(s.metrics.entries==0&&s.result.history.isEmpty()&&s.result.output==null,"actual sourced rejection clears every stable/product prefix");noStableAudit(f,s);}
    static void cases()throws Exception {
        Snapshot x=bind(true,"!anchor(1); !@u p(u);"),rule=bind(false,"!@u p(u)&&b(u)->r(u);"),donor=bind(false,"!b(1);"),opposite=bind(false,"!~r(1);");Packet p=ContextPrivateWitnessPoolRunner.common(x);Set<Source> expected=new HashSet<>();expected.add(x.primary.stream().filter(e->e.statement.contains("p(")).findFirst().get().source);expected.add(rule.primary.get(0).source);expected.add(donor.primary.get(0).source);expected.add(opposite.primary.get(0).source);
        List<List<Snapshot>> orders=permutations(Arrays.asList(rule,donor,opposite));require(orders.size()==6,"all three-cut permutations enumerated");for(List<Snapshot> order:orders){Frame f=new Frame(x,order,p,Collections.emptyMap());SessionRun r=run(f,8,WORK,4096);reject(f,r,2);require(r.result.refutations.containsKey(Cut.of(opposite)),"new common production qualified against independent negative on NEXT barrier in all6 orders");for(Refutation rejection:r.result.refutations.values())for(Proof proof:rejection.proofs)require(proof.support.depth==2&&proof.support.sources.equals(expected),"exact empty2/full four physical Sources in any order");}
        Snapshot anchor=bind(true,"!anchor(1);"),yes=bind(false,"!p(1);"),no=bind(false,"!~p(1);");Packet ap=ContextPrivateWitnessPoolRunner.common(anchor);for(List<Snapshot> order:Arrays.asList(Arrays.asList(yes,no),Arrays.asList(no,yes))){Frame f=new Frame(anchor,order,ap,Collections.emptyMap());SessionRun r=stable(f,1);require(r.result.output.packet.items.size()==1&&r.result.symbolicOutput.units.isEmpty()&&r.result.compoundOutput.clauses.isEmpty(),"independent contradictory raw opinions remain private under unrelated X anchor");}
        Snapshot group=ContextProductionNativeBinding.trusted("collision",Arrays.asList(yes,no),WORK);Map<Cut,org.kanger.ContextUniversalFrozenConstraints.Result> checks=new LinkedHashMap<>();for(Snapshot receiver:new Snapshot[]{null,group}){org.kanger.ContextUniversalFrozenConstraints.Result r=ContextUniversalFrozenConstraints.closeSigned(ContextUniversalCompoundExchangeRunner.rows(anchor,receiver),ap,null,16,16,512,256,WORK);require(r.closed,r.reason);checks.put(receiver==null?Cut.of(anchor):Cut.of(receiver),r);}require(checks.get(Cut.of(group)).foreignRefuted&&!checks.get(Cut.of(group)).xRefuted,"explicit trusted union exposes foreign-only internal collision");org.kanger.ContextUniversalCompoundExchange.Collection entry=org.kanger.ContextUniversalCompoundExchange.collect(anchor,ap,new ArrayList<>(checks.keySet()),checks,512,256,16,WORK);require(!entry.collected&&entry.output==null,"refuted trusted cut cannot mint complete initial carrier; entry refusal, not stable output");
        Snapshot bad=bind(false,"!b(1); !~r(1);"),late=bind(false,"!$u later(u);");PrivatePool pool=ContextWitnessResultTransport.privatePool(p,x,late,WORK);Frame valid=new Frame(x,Arrays.asList(rule,bad,late),p,Collections.singletonMap(pool.cut,pool));SessionRun missing=ContextUniversalGroupedRounds.runWithValidationReuse(x,valid.cuts,p,Collections.emptyMap(),valid.units,valid.compounds,valid.limits,valid.local,8,WORK,4096);incomplete(missing,"later invalid private cut suppresses earlier real contradiction");require(missing.result.phase.equals("checks")&&missing.result.reason.contains("Missing actual full original witness row"),"complete all-cut verification before ANY refutation/product");noStableAudit(valid,missing);reject(valid,run(valid,8,WORK,4096),1);
        Snapshot px=bind(true,"!anchor(1); !@u @v a(u,1)&&b(u,v)->r(u,v);"),pa=bind(false,"!$u $v a(u,1)&&a(v,1)&&hidden(u,1);"),pb=bind(false,"!@u b(u,2); !@u ~r(u,2);");Packet pc=ContextPrivateWitnessPoolRunner.common(px);PrivatePool pp=ContextWitnessResultTransport.privatePool(pc,px,pa,WORK);Set<Source> privateSources=new HashSet<>();privateSources.add(px.primary.stream().filter(e->e.statement.contains("b(")).findFirst().get().source);privateSources.add(pa.primary.get(0).source);for(org.kanger.ContextProductionNativeBinding.Entry e:pb.primary)privateSources.add(e.source);
        Map<Cut,Set<org.kanger.ContextProductionCapture.Support>> privateEvidence=null;
        for(List<Snapshot> order:Arrays.asList(Arrays.asList(pa,pb),Arrays.asList(pb,pa))){Frame f=new Frame(px,order,pc,Collections.singletonMap(pp.cut,pp));SessionRun r=run(f,8,WORK,4096);reject(f,r,1);require(r.result.refutations.containsKey(pp.cut),"universal negative checked against actual private witness input in either order");Map<Cut,Set<org.kanger.ContextProductionCapture.Support>> current=new LinkedHashMap<>();for(Refutation rejection:r.result.refutations.values()){Set<org.kanger.ContextProductionCapture.Support> supports=new HashSet<>();for(Proof proof:rejection.proofs){require(proof.support.depth<=16&&proof.support.sources.equals(privateSources),"private rejection keeps whole witness row and all actual rule Sources");supports.add(proof.support);}current.put(rejection.cut,supports);}if(privateEvidence!=null)require(privateEvidence.equals(current),"same complete per-cut Source/grade rejection evidence in both private orders");privateEvidence=current;ContextUniversalGroupedRounds.Result legacy=ContextUniversalGroupedRounds.run(px,order,pc,f.pools,f.units,f.compounds,f.limits,f.local,8,WORK);require(legacy.status==Status.REFUTED,legacy.phase+": "+legacy.reason);Map<Cut,Set<org.kanger.ContextProductionCapture.Support>> reference=new LinkedHashMap<>();for(Refutation rejection:legacy.refutations.values()){Set<org.kanger.ContextProductionCapture.Support> supports=new HashSet<>();for(Proof proof:rejection.proofs)supports.add(proof.support);reference.put(rejection.cut,supports);}require(reference.equals(current),"private sourced rejection grades equal ordinary reference, no assumed uniform grade");}
        System.out.println("CONTINUATION_REFUTATIONS threeCutOrders=6 independentOpinionOrders=2 trustedEntryRefused=true lateInvalidCutAtomic=true privateRefutationOrders=2");
    }
    public static void main(String[] args){try{System.setProperty("user.home",java.nio.file.Files.createTempDirectory("continuation-refutations-").toString());cases();System.out.println("MATRIX_SCOPES audits="+audits+" receiptRechecks="+receipts+" continuations="+continuations);System.out.println("CONTEXT_UNIVERSAL_CONTINUATION_REFUTATION_PASS checks="+checks);System.exit(0);}catch(Throwable e){e.printStackTrace();System.exit(1);}}
}
